package com.studyspace.model;
import com.fasterxml.jackson.annotation.JsonProperty; import java.time.LocalDate; import java.time.Instant; import org.springframework.data.annotation.Id; import org.springframework.data.mongodb.core.mapping.Document;
@Document("tasks") public class Task { @Id private String id; private String user; private String title; private String subject; private LocalDate dueDate; private String priority="Medium"; private boolean completed=false; private String notes=""; private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now();
 @JsonProperty("_id") public String getId(){return id;} public void setId(String v){id=v;} public String getUser(){return user;} public void setUser(String v){user=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getSubject(){return subject;} public void setSubject(String v){subject=v;} public LocalDate getDueDate(){return dueDate;} public void setDueDate(LocalDate v){dueDate=v;} public String getPriority(){return priority;} public void setPriority(String v){priority=v;} public boolean isCompleted(){return completed;} public void setCompleted(boolean v){completed=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} public Instant getCreatedAt(){return createdAt;} public void setCreatedAt(Instant v){createdAt=v;} public Instant getUpdatedAt(){return updatedAt;} public void setUpdatedAt(Instant v){updatedAt=v;} }
